-- The single-queue claim after this change, generated from autumn/src/job.rs by extract_claim.py.
PREPARE claim(text, text, text[]) AS
UPDATE autumn_jobs SET status = 'running', started_at = NOW(), claimed_by = $1, claimed_at = NOW(), pending_unique_key = CASE WHEN unique_window = 'pending' THEN unique_key ELSE NULL END, unique_key = CASE WHEN unique_window = 'pending' THEN NULL ELSE unique_key END WHERE id = ( SELECT candidate.id FROM autumn_jobs candidate WHERE candidate.status = 'enqueued' AND candidate.run_at <= NOW() AND candidate.queue = $2 AND (candidate.concurrency_limit IS NULL OR COALESCE(( ( SELECT jsonb_object_agg(busy.k, busy.n) FROM ( SELECT jsonb_build_array(running.name, running.concurrency_key)::text AS k, COUNT(*) AS n FROM autumn_jobs running WHERE running.status = 'running' GROUP BY running.name, running.concurrency_key ) busy ) ->> jsonb_build_array(candidate.name, candidate.concurrency_key)::text )::bigint, 0) < candidate.concurrency_limit) AND NOT (candidate.name = ANY($3)) ORDER BY candidate.run_at ASC LIMIT 1 FOR UPDATE SKIP LOCKED ) RETURNING id, name, queue, payload::TEXT AS payload, status, attempt, max_attempts, initial_backoff_ms, enqueued_at, run_at, started_at, finished_at, claimed_by, claimed_at, last_error;
-- pg_ack_success, verbatim.
PREPARE ack(text, text) AS
UPDATE autumn_jobs SET status = 'completed', finished_at = NOW(), claimed_by = NULL, claimed_at = NULL, last_error = NULL WHERE id = $1 AND claimed_by = $2 AND status = 'running';
